from __future__ import annotations

from pathlib import Path
import re


ROOT = Path(__file__).resolve().parents[2]


def _env_port_defaults() -> dict[str, str]:
    defaults: dict[str, str] = {}
    for line in (ROOT / ".env.example").read_text(encoding="utf-8").splitlines():
        if line.startswith("#") or "=" not in line:
            continue
        key, value = line.split("=", 1)
        if key.endswith("_PORT") and value.isdigit():
            defaults[key] = value
    return defaults


def test_active_readme_port_assignments_match_env_example() -> None:
    env_defaults = _env_port_defaults()
    paths = [
        ROOT / "README.md",
        *sorted((ROOT / "services").glob("*/README.md")),
        *sorted((ROOT / "services").glob("*/*/README.md")),
    ]
    allowed_overrides = {
        ("services/openclaw/README.md", "OPENCLAW_LOCALHOST_PORT", "18789"),
        ("services/jupyterhub/README.md", "JUPYTERHUB_PORT", "64094"),
    }
    mismatches: list[str] = []

    for path in paths:
        text = path.read_text(encoding="utf-8", errors="ignore")
        relative = path.relative_to(ROOT).as_posix()
        for match in re.finditer(r"\b([A-Z][A-Z0-9_]+_PORT)\s*=\s*([0-9]{4,5})\b", text):
            var_name, value = match.groups()
            if var_name not in env_defaults:
                continue
            if (relative, var_name, value) in allowed_overrides:
                continue
            if env_defaults[var_name] != value:
                line = text[: match.start()].count("\n") + 1
                mismatches.append(
                    f"{relative}:{line}: {var_name}={value}, .env.example has {env_defaults[var_name]}"
                )

    assert not mismatches, "\n".join(mismatches)

from __future__ import annotations

import re
from pathlib import Path


ROOT = Path(__file__).resolve().parents[2]


PORT_FALLBACK_RE = re.compile(r"\$\{(?P<var>[A-Z0-9_]+):-?(?P<fallback>\d{4,5})\}")


def _env_example_values() -> dict[str, str]:
    values: dict[str, str] = {}
    for line in (ROOT / ".env.example").read_text(encoding="utf-8").splitlines():
        if not line or line.startswith("#") or "=" not in line:
            continue
        key, value = line.split("=", 1)
        values[key] = value
    return values


def test_compose_port_fallbacks_match_env_example_defaults() -> None:
    env = _env_example_values()
    mismatches: list[str] = []

    for compose in sorted((ROOT / "services").glob("*/compose.yml")):
        text = compose.read_text(encoding="utf-8")
        for match in PORT_FALLBACK_RE.finditer(text):
            var = match.group("var")
            fallback = match.group("fallback")
            if not var.endswith("_PORT") or var not in env:
                continue
            if env[var] and env[var] != fallback:
                mismatches.append(
                    f"{compose.relative_to(ROOT)} uses ${{{var}:-{fallback}}}; "
                    f".env.example has {var}={env[var]}"
                )

    assert not mismatches, "\n".join(mismatches)

"""Guard against nested file/dir bind-mounts into a read-only parent mount.

Regression test for the litellm-init mount bug: mounting a file at
``/catalog/ollama-models.yaml`` while ``/catalog`` is itself a ``:ro`` bind
mount makes runc fail at container init ("make mountpoint ... read-only file
system") on Docker 29.x / macOS, aborting ``docker compose up``.

The invariant: within a single compose service, no volume target may be nested
under another volume target that is mounted read-only. (A writable parent is
fine — the runtime can create the mountpoint; a fresh, non-bind-mounted parent
dir is also fine.)
"""
from __future__ import annotations

import pathlib

import pytest
import yaml

REPO_ROOT = pathlib.Path(__file__).resolve().parent.parent.parent
COMPOSE_FILES = sorted((REPO_ROOT / "services").glob("*/compose.yml"))

# Compose short-volume mode tokens that mean "read-only".
_RO_TOKENS = {"ro"}


def _parse_short_volume(vol: str) -> tuple[str, bool] | None:
    """Return (container_target, is_read_only) for a short-form volume string.

    Handles ``SOURCE:TARGET[:MODE]``. The target is the first ``/``-rooted
    segment after the source. Returns None when no absolute target is found
    (e.g. env-substituted or malformed entries we don't reason about).
    """
    parts = vol.split(":")
    # Find the container target: the first segment (index >= 1) starting with "/".
    target_idx = next(
        (i for i in range(1, len(parts)) if parts[i].startswith("/")), None
    )
    if target_idx is None:
        return None
    target = parts[target_idx].rstrip("/") or "/"
    mode_tokens = set()
    for seg in parts[target_idx + 1:]:
        mode_tokens.update(seg.split(","))
    return target, bool(_RO_TOKENS & mode_tokens)


def _service_volume_targets(service: dict) -> list[tuple[str, bool]]:
    out: list[tuple[str, bool]] = []
    for vol in service.get("volumes", []) or []:
        if isinstance(vol, str):
            parsed = _parse_short_volume(vol)
            if parsed:
                out.append(parsed)
        elif isinstance(vol, dict):  # long form
            target = vol.get("target")
            if isinstance(target, str) and target.startswith("/"):
                out.append((target.rstrip("/") or "/", bool(vol.get("read_only"))))
    return out


@pytest.mark.parametrize("compose_path", COMPOSE_FILES, ids=lambda p: p.parent.name)
def test_no_mount_nested_under_readonly_parent(compose_path):
    data = yaml.safe_load(compose_path.read_text(encoding="utf-8")) or {}
    services = data.get("services", {}) or {}
    violations: list[str] = []
    for svc_name, svc in services.items():
        targets = _service_volume_targets(svc)
        for parent, parent_ro in targets:
            if not parent_ro:
                continue
            for child, _ in targets:
                if child != parent and child.startswith(parent + "/"):
                    violations.append(
                        f"{compose_path.relative_to(REPO_ROOT)} :: service '{svc_name}': "
                        f"'{child}' is mounted INSIDE read-only mount '{parent}' — "
                        f"runc cannot create the mountpoint in a :ro bind mount. "
                        f"Mount it outside '{parent}' (a separate dir) instead."
                    )
    assert not violations, "Nested-into-:ro bind mount(s):\n" + "\n".join(violations)

"""Merge research rows + candidates into the master integration matrix.

Reads:
  docs/research/rows/<service>.md
  docs/research/candidates/<slug>.md

Writes:
  docs/research/integration-matrix.md           — generated index
  docs/research/candidates/<slug>.md            — referenced-by frontmatter
                                                   updated in place

Deterministic and idempotent: re-running produces byte-identical output.
"""

from __future__ import annotations

import argparse
from datetime import date
from urllib.parse import urlsplit
import json
import re
import sys
from pathlib import Path

import yaml

REPO_ROOT = Path(__file__).resolve().parent.parent.parent
DEFAULT_ROOT = REPO_ROOT / "docs" / "research"

_FRONTMATTER_RE = re.compile(r"^---\n(.*?)\n---\n(.*)$", re.DOTALL)
_CAND_REF_RE = re.compile(r"\.\./candidates/([\w-]+)\.md")
# Lifecycles that end a candidacy (#1190): the record stays under
# candidates/ as history, but no derived index lists it as a candidate.
CLOSED_LIFECYCLES = frozenset({"shipped", "rejected"})


def _parse(text: str) -> tuple[dict, str] | None:
    m = _FRONTMATTER_RE.match(text)
    if not m:
        return None
    try:
        fm = yaml.safe_load(m.group(1)) or {}
    except (yaml.YAMLError, ValueError):  # ValueError: an impossible date
        return None
    if not isinstance(fm, dict):
        return None
    return fm, m.group(2)


def _scalar(value, *, in_flow: bool = False):
    """``value`` as written, quoted only when YAML would read it back as
    something else: an unquoted ` #` truncated it and `: ` made the file
    unparseable on the next regen (2026-10-08 run, cycle 43)."""
    if not isinstance(value, str):
        return value
    text = f"[{value}]" if in_flow else value
    try:
        loaded = yaml.safe_load(f"k: {text}")
    except yaml.YAMLError:
        loaded = None
    expected = [value] if in_flow else value
    return value if loaded == {"k": expected} else json.dumps(value, ensure_ascii=False)


def _emit_frontmatter(fm: dict) -> str:
    """Emit YAML frontmatter deterministically. Uses inline (`[a, b]`) form for
    short lists to match the existing example fixtures."""
    lines = ["---"]
    for k in sorted(fm.keys()):
        v = fm[k]
        if isinstance(v, list):
            if all(isinstance(x, str) for x in v) and len(v) <= 8:
                rendered = "[" + ", ".join(str(_scalar(x, in_flow=True)) for x in v) + "]"
                lines.append(f"{k}: {rendered}")
            else:
                lines.append(f"{k}:")
                for item in v:
                    lines.append(f"  - {_scalar(item)}")
        else:
            lines.append(f"{k}: {_scalar(v)}")
    lines.append("---")
    return "\n".join(lines) + "\n"


def closed_candidate_slugs(root: Path = DEFAULT_ROOT) -> frozenset[str]:
    """Slugs of candidates whose lifecycle is shipped or rejected."""
    closed = set()
    for path in sorted((root / "candidates").glob("*.md")):
        if path.name == "README.md":
            continue
        parsed = _parse(path.read_text(encoding="utf-8"))
        if parsed and parsed[0].get("lifecycle") in CLOSED_LIFECYCLES:
            closed.add(str(parsed[0].get("slug", path.stem)))
    return frozenset(closed)



def _public_text(fields: dict, key: str, path: Path) -> str:
    value = fields.get(key)
    if not isinstance(value, str) or not value.strip():
        raise ValueError(f"{path}: {key} must be a non-empty string")
    return value


def _public_decision_date(fields: dict, path: Path) -> date | None:
    value = fields.get("decided")
    if value is None and fields["lifecycle"] == "proposed":
        return None
    if type(value) not in (str, date) or not re.fullmatch(r"\d{4}-\d{2}-\d{2}", str(value)):
        raise ValueError(f"{path}: decided must be YYYY-MM-DD")
    try:
        return date.fromisoformat(str(value))
    except ValueError as exc:
        raise ValueError(f"{path}: decided must be a real calendar date") from exc


def _public_decision(fields: dict, path: Path) -> dict:
    record = {key: _public_text(fields, key, path) for key in (
        "slug", "name", "lifecycle", "upstream", "public-summary",
    )}
    slug = record["slug"]
    if not re.fullmatch(r"[a-z0-9]+(?:-[a-z0-9]+)*", slug) or slug != path.stem:
        raise ValueError(f"{path}: slug must be safe and match the record basename")
    if record["lifecycle"] not in {"proposed", "planned", "deferred", "shipped", "rejected"}:
        raise ValueError(f"{path}: lifecycle is not a recognized candidate lifecycle")
    upstream = record["upstream"]
    try:
        parsed = urlsplit(upstream)
    except ValueError as exc:
        raise ValueError(f"{path}: upstream must be an http(s) project URL") from exc
    if parsed.scheme not in {"http", "https"} or not parsed.netloc or re.search(r"\s", upstream):
        raise ValueError(f"{path}: upstream must be an http(s) project URL")
    record["decided"] = _public_decision_date(fields, path)
    return record


def load_public_decisions(root: Path = DEFAULT_ROOT) -> list[dict]:
    """Load only opted-in decision metadata; internal research bodies stay private."""
    records = {}
    for path in sorted((root / "candidates").glob("*.md")):
        if path.name == "README.md":
            continue
        text = path.read_text(encoding="utf-8")
        parsed = _parse(text)
        if parsed is None:
            if re.search(r"(?m)^public-summary\s*:", text):
                raise ValueError(f"{path}: public-summary has unparseable front matter")
            continue
        if "public-summary" not in parsed[0]:
            continue
        record = _public_decision(parsed[0], path)
        if record["slug"] in records:
            raise ValueError(f"{path}: duplicate public candidate slug {record['slug']}")
        records[record["slug"]] = record
    return [records[slug] for slug in sorted(records)]


def _write_or_check(path: Path, text: str, check: bool) -> bool:
    """True when ``path`` differs from ``text``; writes it unless checking."""
    if path.exists() and path.read_text(encoding="utf-8") == text:
        return False
    if not check:
        path.write_text(text, encoding="utf-8")
    return True


def run_merge(root: Path, *, check: bool = False) -> list[Path]:
    """Merge research artifacts under `root` (a Path pointing at docs/research/).

    Returns the files that changed (or, with ``check``, would change).
    """

    rows_dir = root / "rows"
    cands_dir = root / "candidates"

    rows: list[tuple[Path, dict, str]] = []
    if rows_dir.is_dir():
        for p in sorted(rows_dir.glob("*.md")):
            if p.name in ("README.md", ".gitkeep"):
                continue
            parsed = _parse(p.read_text(encoding="utf-8"))
            if parsed:
                rows.append((p, parsed[0], parsed[1]))

    cands: dict[str, tuple[Path, dict, str]] = {}
    if cands_dir.is_dir():
        for p in sorted(cands_dir.glob("*.md")):
            if p.name in ("README.md", ".gitkeep"):
                continue
            parsed = _parse(p.read_text(encoding="utf-8"))
            if parsed:
                cands[parsed[0].get("slug", p.stem)] = (p, parsed[0], parsed[1])

    referenced_by: dict[str, set[str]] = {slug: set() for slug in cands}
    for _, fm, body in rows:
        svc = fm.get("service", "")
        for slug in _CAND_REF_RE.findall(body):
            if slug in referenced_by:
                referenced_by[slug].add(svc)

    changed: list[Path] = []
    for slug, (path, fm, body) in cands.items():
        new_fm = dict(fm)
        new_fm["referenced-by"] = sorted(referenced_by.get(slug, set()))
        new_text = _emit_frontmatter(new_fm) + "\n" + body.lstrip("\n")
        if _write_or_check(path, new_text, check):
            changed.append(path)

    out_path = root / "integration-matrix.md"
    if _write_or_check(out_path, _build_matrix(rows, cands, referenced_by), check):
        changed.append(out_path)
    return changed


def _build_matrix(
    rows: list[tuple[Path, dict, str]],
    cands: dict[str, tuple[Path, dict, str]],
    referenced_by: dict[str, set[str]],
) -> str:
    """Build the integration-matrix.md content."""

    lines: list[str] = []
    lines.append("# Cross-service Integration Matrix")
    lines.append("")
    lines.append(
        "> **Generated** by `python -m bootstrapper.docs.merge_research`. "
        "Do not edit by hand — your changes will be overwritten on the next run."
    )
    lines.append("")
    lines.append("## 1. By service")
    lines.append("")
    lines.append("| Service | Category | Sources | Row file |")
    lines.append("|---|---|---|---|")
    for _, fm, _body in sorted(rows, key=lambda r: r[1].get("service", "")):
        svc = fm.get("service", "?")
        cat = fm.get("category", "?")
        src_count = len(fm.get("sources_consulted") or [])
        lines.append(f"| {svc} | {cat} | {src_count} | [rows/{svc}.md](./rows/{svc}.md) |")
    lines.append("")

    by_cat: dict[str, list[str]] = {}
    for _, fm, _body in rows:
        by_cat.setdefault(fm.get("category", "?"), []).append(fm.get("service", "?"))
    lines.append("## 2. By category")
    lines.append("")
    for number, cat in enumerate(sorted(by_cat), start=1):
        lines.append(f"### 2.{number}. {cat}")
        lines.append("")
        for svc in sorted(by_cat[cat]):
            lines.append(f"- [{svc}](./rows/{svc}.md)")
        lines.append("")

    lines.extend(_candidate_lines(cands, referenced_by))
    return "\n".join(lines).rstrip() + "\n"


def _candidate_lines(
    cands: dict[str, tuple[Path, dict, str]],
    referenced_by: dict[str, set[str]],
) -> list[str]:
    """The "Candidate new services" section: open candidates only (#1190)."""
    lines = ["## 3. Candidate new services", ""]
    active = sorted(
        slug for slug, (_p, fm, _b) in cands.items()
        if fm.get("lifecycle") not in CLOSED_LIFECYCLES
    )
    if len(active) < len(cands):
        lines.append(
            "Shipped and rejected candidates are not listed; their one-pagers stay "
            "under `candidates/` with the `lifecycle` that closed them."
        )
        lines.append("")
    if active:
        lines.append("| Candidate | Category fit | Referenced by | One-pager |")
        lines.append("|---|---|---|---|")
        for slug in active:
            _, fm, _body = cands[slug]
            name = fm.get("name", slug)
            cat_fit = fm.get("category-fit", "?")
            refs = sorted(referenced_by.get(slug, set()))
            refs_str = ", ".join(refs) if refs else "_(none)_"
            lines.append(f"| {name} | {cat_fit} | {refs_str} | [candidates/{slug}.md](./candidates/{slug}.md) |")
    else:
        lines.append("_No candidate new services proposed._")
    lines.append("")
    return lines


def main(argv: list[str]) -> int:
    ap = argparse.ArgumentParser(prog="bootstrapper.docs.merge_research")
    ap.add_argument("--research-root", type=Path, default=DEFAULT_ROOT)
    ap.add_argument(
        "--check", action="store_true",
        help="report files merge would rewrite and exit 2 instead of writing them",
    )
    args = ap.parse_args(argv)
    if not args.research_root.is_dir():
        print(f"error: research root not found: {args.research_root}", file=sys.stderr)
        return 1
    changed = run_merge(args.research_root, check=args.check)
    if args.check and changed:
        for path in changed:
            print(f"drift: {path}", file=sys.stderr)
        return 2
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path
